class Lamp {
  constructor(colour) {
    this.colour = colour;
  }

  describe() {
    return `${this.colour} lamp`;
  }
}

const lamp = new Lamp("red");

console.log(typeof Lamp);
console.log(typeof lamp);
console.log(Object.hasOwn(lamp, "describe"));
console.log(Lamp.prototype.constructor === Lamp);
console.log(lamp.constructor.name);
console.log(Object.keys(lamp).length);
